import math

def gauss_reduction(v1, v2):
    """Gauss-Lagrange 2D Lattice Reduction."""
    u, v = v1, v2
    while True:
        if u[0]**2 + u[1]**2 &gt; v[0]**2 + v[1]**2:
            u, v = v, u
        mu = (u[0]*v[0] + u[1]*v[1]) / (u[0]**2 + u[1]**2)
        q = round(mu)
        if q == 0:
            break
        v = (v[0] - q*u[0], v[1] - q*u[1])
        if v[0]**2 + v[1]**2 &lt; u[0]**2 + u[1]**2:
            u, v = v, u
    return u, v

