// Extract greatest common divisor with zero hardware division
#include &lt;stdint.h&gt;

static inline uint64_t fast_gcd(uint64_t u, uint64_t v) {
    if (!u || !v) return u | v;
    int shift = __builtin_ctzll(u | v);
    u &gt;&gt;= __builtin_ctzll(u);
    do {
        v &gt;&gt;= __builtin_ctzll(v);
        if (u &gt; v) { uint64_t t = v; v = u; u = t; }
        v -= u;
    } while (v);
    return u &lt;&lt; shift;
}
